"""
sftp_service - Dienst fuer SFTP-Operationen.

Verwendung:
    from core_services.transfer import download_files_from_sftp, upload_file_to_sftp
"""

import logging
import os

import paramiko
from paramiko import SFTPClient, Transport

from ..config_service import SftpConfig
from ..utils.progress_logging import iter_with_progress

logger = logging.getLogger(__name__)

SFTP_OPERATION_ERRORS = (OSError, EOFError, paramiko.SSHException)


def _close_resource(resource: object | None, resource_name: str) -> None:
    """Schliesst eine SFTP-Ressource und protokolliert Fehler beim Aufraeumen."""
    if resource is None:
        return

    close = getattr(resource, "close", None)
    if close is None:
        return

    try:
        close()
    except SFTP_OPERATION_ERRORS as exc:
        logger.warning(
            "SFTP-Ressource konnte nicht geschlossen werden (%s): %s",
            resource_name,
            exc,
            exc_info=True,
        )


def download_files_from_sftp(
    sftp_config: SftpConfig,
    remote_path: str,
    local_path: str,
) -> int:
    """Laedt alle Dateien aus einem SFTP-Verzeichnis herunter und loescht sie remote.

    Verbindet sich zum SFTP-Server, laedt alle Dateien aus remote_path in
    local_path herunter und entfernt die Dateien anschliessend auf dem Server.

    Args:
        sftp_config: Verbindungsdaten des SFTP-Servers.
        remote_path: Verzeichnispfad auf dem SFTP-Server.
        local_path: Lokaler Zielpfad fuer die heruntergeladenen Dateien.

    Examples:

        Download mit einer SFTP-Konfiguration:

        ```python
        sftp_config = SftpConfig(
            host="sftp.example.invalid",
            port=22,
            username="benutzername",
            password="passwort",
            remote_path="/eingang",
        )

        download_files_from_sftp(
            sftp_config=sftp_config,
            remote_path=sftp_config.remote_path,
            local_path="C:/temp",
        )
        ```

    Returns:
        Anzahl der erfolgreich heruntergeladenen Dateien.

    Raises:
        OSError: Bei lokalen Dateisystem- oder Netzwerkfehlern.
        EOFError: Wenn die SFTP-Verbindung unerwartet beendet wird.
        paramiko.SSHException: Bei SFTP-/SSH-Verbindungsfehlern.
    """
    transport = None
    sftp = None
    try:
        os.makedirs(local_path, exist_ok=True)

        transport = Transport((sftp_config.host, sftp_config.port))
        transport.connect(username=sftp_config.username, password=sftp_config.password)
        sftp = SFTPClient.from_transport(transport)
        if sftp is None:
            raise paramiko.SSHException("SFTP-Client konnte nicht erstellt werden.")
        files = sftp.listdir(remote_path)

        downloaded_files: list[str] = []
        for file in iter_with_progress(logger, files, len(files), "SFTP-Downloads"):
            remote_file = f"{remote_path}/{file}"
            local_file = os.path.join(local_path, file)
            try:
                sftp.get(remote_file, local_file)
                logger.info("Heruntergeladen: %s", file)
                sftp.remove(remote_file)
                logger.info("Geloescht auf SFTP: %s", file)
                downloaded_files.append(file)
            except SFTP_OPERATION_ERRORS as exc:
                logger.error("Fehler bei datei %s: %s", file, exc, exc_info=True)

        return len(downloaded_files)

    except SFTP_OPERATION_ERRORS as exc:
        logger.error("SFTP-Verbindung fehlgeschlagen: %s", exc, exc_info=True)
        raise
    finally:
        _close_resource(sftp, "client")
        _close_resource(transport, "transport")


def upload_file_to_sftp(
    file: str,
    local_file_path: str,
    remote_file_path: str,
    sftp_config: SftpConfig,
) -> None:
    """Laedt eine einzelne datei auf einen SFTP-Server hoch.

    Args:
        file: Name der datei, die hochgeladen werden soll.
        local_file_path: Lokales Verzeichnis, in dem die datei liegt.
        remote_file_path: Zielverzeichnis auf dem SFTP-Server.
        sftp_config: Verbindungsdaten des SFTP-Servers.

    Examples:

        Upload mit einer SFTP-Konfiguration:

        ```python
        sftp_config = SftpConfig(
            host="sftp.example.invalid",
            port=22,
            username="benutzername",
            password="passwort",
            remote_path="/eingang",
        )

        upload_file_to_sftp(
            file="datei.csv",
            local_file_path="C:/temp",
            remote_file_path=sftp_config.remote_path,
            sftp_config=sftp_config,
        )
        ```

    Raises:
        OSError: Bei lokalen Dateisystem- oder Netzwerkfehlern.
        EOFError: Wenn die SFTP-Verbindung unerwartet beendet wird.
        paramiko.SSHException: Bei SFTP-/SSH-Verbindungsfehlern.
    """
    transport = None
    sftp = None
    try:
        transport = paramiko.Transport((sftp_config.host, sftp_config.port))
        transport.connect(username=sftp_config.username, password=sftp_config.password)
        sftp = paramiko.SFTPClient.from_transport(transport)
        if sftp is None:
            raise paramiko.SSHException("SFTP-Client konnte nicht erstellt werden.")

        local_file_path_file = os.path.join(local_file_path, file)
        remote_file_path_file = remote_file_path.rstrip("/") + "/" + file

        sftp.put(local_file_path_file, remote_file_path_file)
        logger.info("datei %s nach %s hochgeladen", file, remote_file_path)

    except SFTP_OPERATION_ERRORS as exc:
        logger.error("Upload von %s fehlgeschlagen: %s", file, exc, exc_info=True)
        raise
    finally:
        _close_resource(sftp, "client")
        _close_resource(transport, "transport")
